using Mono.Cecil;using System.Text.Json;
if(args.Length!=4)throw new Exception("DLL, support directory, patch report, output");var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(args[1]);using var a=AssemblyDefinition.ReadAssembly(args[0],new ReaderParameters{AssemblyResolver=resolver});using var doc=JsonDocument.Parse(File.ReadAllText(args[2]));var tokens=doc.RootElement.GetProperty("methods").EnumerateArray().Select(r=>Convert.ToInt32(r.GetProperty("token").GetString(),16)).ToArray();var rows=new List<object>();int rejected=0,unresolved=0;
bool SameAssembly(TypeDefinition context,TypeDefinition owner)=>context.Module.Assembly.Name.FullName==owner.Module.Assembly.Name.FullName;
bool Family(TypeDefinition context,TypeDefinition owner){for(var t=context;t!=null;t=t.BaseType?.Resolve())if(t.FullName==owner.FullName&&SameAssembly(t,owner))return true;return false;}
bool Allow(TypeDefinition context,TypeDefinition owner,bool pub,bool priv,bool asm,bool fam,bool or,bool and)=>pub||(priv&&context.FullName==owner.FullName&&SameAssembly(context,owner))||(asm&&SameAssembly(context,owner))||(fam&&Family(context,owner))||(or&&(SameAssembly(context,owner)||Family(context,owner)))||(and&&SameAssembly(context,owner)&&Family(context,owner));
foreach(int token in tokens){var m=(MethodDefinition)a.MainModule.LookupToken(token);foreach(var i in m.Body.Instructions){try{if(i.Operand is FieldReference f){var d=f.Resolve()??throw new Exception("Unresolved field");bool allowed=Allow(m.DeclaringType,d.DeclaringType,d.IsPublic,d.IsPrivate,d.IsAssembly,d.IsFamily,d.IsFamilyOrAssembly,d.IsFamilyAndAssembly);if(!allowed)rejected++;rows.Add(new{method=m.FullName,token=$"0x{token:X8}",offset=i.Offset,kind="field",member=f.FullName,owner_assembly=d.Module.Assembly.Name.FullName,attributes=d.Attributes.ToString(),allowed});}else if(i.Operand is MethodReference r){var d=r.Resolve()??throw new Exception("Unresolved method");bool allowed=Allow(m.DeclaringType,d.DeclaringType,d.IsPublic,d.IsPrivate,d.IsAssembly,d.IsFamily,d.IsFamilyOrAssembly,d.IsFamilyAndAssembly);if(!allowed)rejected++;rows.Add(new{method=m.FullName,token=$"0x{token:X8}",offset=i.Offset,kind="method",member=r.FullName,owner_assembly=d.Module.Assembly.Name.FullName,attributes=d.Attributes.ToString(),allowed});}}catch(Exception e){unresolved++;rows.Add(new{method=m.FullName,token=$"0x{token:X8}",offset=i.Offset,allowed=false,error=e.ToString()});}}}
var result=new{pass=rejected==0&&unresolved==0,target_methods=tokens.Length,rejected,unresolved,members=rows,scope="Read-only member visibility checks against exact candidate and supplied assembly metadata. Unknown resolution fails. Public members, same-type private members, assembly and family access checked. Does not replace full CLR/ECMA verification, protected receiver verification, engine or compiler acceptance."};File.WriteAllText(args[3],JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(new{result.pass,result.target_methods,result.rejected,result.unresolved}));return result.pass?0:2;
